1. useScheduleGridStatistics에서 assignments를 watch (deep: true)
2. 변경 시 자동으로 rowStats, columnStats 재계산
3. 통계 행/열에 계산된 값 표시

예시 코드:
```typescript
// useScheduleGridStatistics.ts
export function useScheduleGridStatistics(
  employees: Ref<Employee[]>,
  dates: Ref<GridColumn[]>,
  assignments: Ref<AssignmentMap>
) {
  const rowStats = ref<Record<string, RowStat>>({});
  const columnStats = ref<Record<string, ColumnStat>>({});

  // assignments 변경 감지
  watch(
    () => assignments.value,
    () => {
      calculateStatistics();
    },
    { deep: true, immediate: true }
  );

  function calculateStatistics() {
    // 행 통계 (근무자별)
    rowStats.value = {};
    for (const emp of employees.value) {
      const stat: RowStat = { D: 0, E: 0, N: 0, total: 0 };
      const empAssignments = assignments.value[emp.id] || {};

      for (const shiftCode of Object.values(empAssignments)) {
        if (shiftCode === 'D') stat.D++;
        else if (shiftCode === 'E') stat.E++;
        else if (shiftCode === 'N') stat.N++;
        if (shiftCode !== 'O') stat.total++;
      }

      rowStats.value[emp.id] = stat;
    }

    // 열 통계 (날짜별)
    columnStats.value = {};
    for (const date of dates.value) {
      const stat: ColumnStat = { D: 0, E: 0, N: 0, total: 0 };

      for (const emp of employees.value) {
        const shiftCode = assignments.value[emp.id]?.[date.date];
        if (shiftCode === 'D') stat.D++;
        else if (shiftCode === 'E') stat.E++;
        else if (shiftCode === 'N') stat.N++;
        if (shiftCode && shiftCode !== 'O') stat.total++;
      }

      columnStats.value[date.date] = stat;
    }
  }

  return { rowStats, columnStats };
}
```

