const router = useRouter();
const { status, startSolver, stopPolling } = useAISolver();

const showModal = ref(false);
const isGenerating = ref(false);
const elapsedTime = ref(0);
let timerInterval: number | null = null;

const statusMessage = computed(() => {
  switch (status.value) {
    case 'created': return '요청 생성 중...';
    case 'running': return '처리 중... 잠시만 기다려주세요.';
    case 'complete': return '완료! 결과를 불러오는 중...';
    case 'error': return '오류가 발생했습니다.';
    default: return '';
  }
});

const progress = computed(() => {
  // Mock progress (실제로는 AI Solver가 제공해야 함)
  return Math.min(elapsedTime.value * 2, 95);
});

async function handleGenerate() {
  // 1. 전월 데이터 검증
  const validation = validateLastMonthData(employees.value, dates.value, assignments.value);
  if (!validation.isValid) {
    window.$message.error(`전월 데이터를 모두 입력해주세요: ${validation.errors[0]}`);
    return;
  }

  // 2. Supabase에 schedule 레코드 생성
  const scheduleId = await createSchedule();

  // 3. AI Solver 시작 및 Polling
  showModal.value = true;
  isGenerating.value = true;
  elapsedTime.value = 0;

  // 타이머 시작
  timerInterval = setInterval(() => {
    elapsedTime.value++;
  }, 1000);

  try {
    await startSolver(scheduleId, {
      employees: employees.value,
      assignments: assignments.value,
      // ... 기타 필요한 데이터
    });

    // 4. 완료 시 Step 4로 이동
    if (status.value === 'complete') {
      localStorage.removeItem(`everyshift_temp_schedule_${scheduleStore.basicInfo!.month}`);
      router.push(`/schedule/step4?scheduleId=${scheduleId}`);
    }
  } catch (error) {
    window.$message.error('근무표 생성 중 오류가 발생했습니다.');
  } finally {
    isGenerating.value = false;
    if (timerInterval) clearInterval(timerInterval);
  }
}

function handleCancel() {
  stopPolling();
  showModal.value = false;
  isGenerating.value = false;
  if (timerInterval) clearInterval(timerInterval);
}

onUnmounted(() => {
  stopPolling();
  if (timerInterval) clearInterval(timerInterval);
});
</script>
